///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchNoticeList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchNoticeList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeList",
        method: "post",
        action: "/main/notice.do?method=searchNoticeList",
        ref: "dma_searchNoticeListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf00101.tx_fn_searchNoticeList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_searchNoticeSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchNoticeSpec = async function () {
    const sbmOptions = {
        id: "tx_fn_searchNoticeSpec",
        method: "post",
        action: "/main/notice.do?method=searchNoticeSpec",
        ref: "dma_searchNoticeSpecReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf00101.tx_fn_searchNoticeSpec" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchNoticeList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchNoticeList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchNoticeList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    fm.action = '/main/notice.do?method=searchNoticeList';
    await scwin.tx_fn_searchNoticeList();
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchNoticeSpec
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId
 * @returns
 * @hidden N
*/
scwin.searchNoticeSpec = async function (contnId) {
    /* sdd-asis-lifecycle:begin fn_searchNoticeSpec — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=searchNoticeSpec';
    await scwin.tx_fn_searchNoticeSpec();
    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId attachFileNm
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (contnId, attachFileNm) {
    /* sdd-asis-lifecycle:begin fn_fileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (attachFileNm == null || attachFileNm === "") {
        await $c.win.alert("첨부파일이 없습니다.");
        return;
    }
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchNoticeListReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_fileDown();
    return;
    /* sdd-asis-lifecycle:end */
};
